pub fn compute_semantic_anchors(db: &Db, workspace_root: &Path) -> Result<usize> {
    let components = db.all_components()?;
    if components.is_empty() {
        return Ok(0);
    }

    // Build lookup tables (one pass each)
    let sym_file_map: HashMap<i64, i64> = db.all_symbol_file_map()?...;
    let all_refs = db.all_resolved_refs()?;
    let churn_map = git::git_churn(workspace_root, 90).unwrap_or_default();

    // Build component → file_ids mapping from membership
    // Build file_id → component_id reverse map
    // Build per-symbol in-degree-within-component counts

    for component in &components {
        let file_ids = component_file_ids[&component.id];
        let component_file_set: HashSet<i64> = file_ids.iter().copied().collect();

        // Gather all symbols in this component's files
        let mut symbols: Vec<SymbolRow> = Vec::new();
        for &fid in &file_ids {
            symbols.extend(db.find_symbols_by_file(fid)?);
        }

        // Filter to anchor-eligible kinds (function, struct, enum, trait, method, type_alias, const)
        // Exclude: module, import, field, variable, parameter
        let eligible: Vec<&SymbolRow> = symbols.iter()
            .filter(|s| ANCHOR_KINDS.contains(&s.kind.as_str()))
            .filter(|s| s.parent_symbol_id.is_none() || s.kind == "method")
            .collect();

        // Score each eligible symbol
        for sym in &eligible {
            let in_degree = intra_component_refs[sym.id];  // pre-computed
            let pagerank = sym.pagerank.unwrap_or(0.0);
            let file_path = file_id_to_path[sym.file_id];
            let file_churn = churn_map.get(file_path).copied().unwrap_or(0);
            let stability = 1.0 / (1.0 + file_churn as f64);
            let naming = name_alignment(&sym.short_name, &component.name);

            // Normalize and combine
            // (normalization: divide each by max in this component, or use rank-based)
        }

        // Select top-N (adaptive: 3 for <15 symbols, 5 for 15-50, 7 for 50+)
        // Build anchor rows
    }

    db.batch_replace_anchors(&component_ids, &anchor_rows)?;
    Ok(total_anchors)
}
```

**Normalization**: Rank-based normalization within each component. For each signal, rank symbols 0..N-1, then normalize to [0, 1] by dividing by (N-1). This avoids issues with outlier values in raw scores.

**Weights**: in_degree=0.35, pagerank=0.30, stability=0.20, naming=0.15

**Anchor count formula**: `clamp(eligible_count / 8, 3, 7)` — gives 3 for ≤24 eligible symbols, 5 for 25-40, 7 for 56+.

**Naming alignment**: Tokenize both names (split on `_`, camelCase boundaries). Compute Jaccard coefficient of token sets. `"parse"` and `"Parser"` → tokens `{"parse"}` and `{"parser"}` → overlap after lowercasing = 1.0.

